import json
import pandas as pd

records = {}


def norm(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return ''
    return str(v).strip()


def add(email, phone, status):
    email = norm(email).lower()
    if not email:
        return
    phone = norm(phone)
    status = norm(status)
    cur = records.setdefault(email, {'email': email, 'phone': '', 'status': ''})
    if not cur['phone'] and phone:
        cur['phone'] = phone
    if not cur['status'] and status:
        cur['status'] = status


# users.csv
users = pd.read_csv('/workspace/users.csv', dtype=str, keep_default_na=False)
for rec in users.to_dict('records'):
    add(rec.get('email'), rec.get('phone'), rec.get('status'))

# records.jsonl
with open('/workspace/records.jsonl', encoding='utf-8') as f:
    for line in f:
        if line.strip():
            rec = json.loads(line)
            add(rec.get('email'), rec.get('phone'), rec.get('status'))

# profiles.json (dict keyed by email, phone nested in other_info)
with open('/workspace/profiles.json', encoding='utf-8') as f:
    profiles = json.load(f)
if isinstance(profiles, dict):
    items = list(profiles.items())
else:
    items = [(None, p) for p in profiles]
for key, rec in items:
    other = rec.get('other_info') or {}
    phone = rec.get('phone') or other.get('phone')
    add(rec.get('email') or key, phone, rec.get('status'))

out = pd.DataFrame(list(records.values()), columns=['email', 'phone', 'status'])
out.to_csv('/workspace/merged_records.csv', index=False)
print('wrote', len(out), 'unique emails')
EOF
